function pairSum(sorted, target) {
  let lo = 0;
  let hi = sorted.length - 1;
  let probes = 0;
  while (lo < hi) {
    probes++;
    const sum = sorted[lo] + sorted[hi];
    if (sum === target) return { pair: [sorted[lo], sorted[hi]], probes };
    if (sum < target) lo++;
    else hi--;
  }
  return { pair: null, probes };
}
