function hasCycle(graph) {
  const color = new Map();
  const visit = (n) => {
    if (color.get(n) === 'grey') return true;
    if (color.get(n) === 'black') return false;
    color.set(n, 'grey');
    for (const nb of graph[n]) if (visit(nb)) return true;
    color.set(n, 'black');
    return false;
  };
  return Object.keys(graph).some(visit);
}
