function minCapacity(weights, days) {
  const canDo = (cap) => {
    let used = 1;
    let load = 0;
    for (const w of weights) {
      if (load + w > cap) { used++; load = 0; }
      load += w;
    }
    return used <= days;
  };
  let lo = Math.max(...weights);
  let hi = weights.reduce((a, b) => a + b, 0);
  let probes = 0;
  while (lo < hi) {
    probes++;
    const mid = (lo + hi) >> 1;
    if (canDo(mid)) hi = mid;
    else lo = mid + 1;
  }
  return { cap: lo, probes };
}
