function quickselect(arr, k) {
  const a = [...arr];
  let lo = 0;
  let hi = a.length - 1;
  while (true) {
    const pivot = a[hi];
    let store = lo;
    for (let i = lo; i < hi; i++) {
      if (a[i] > pivot) { [a[i], a[store]] = [a[store], a[i]]; store++; }
    }
    [a[store], a[hi]] = [a[hi], a[store]];
    if (store === k) return a[store];
    if (store < k) lo = store + 1;
    else hi = store - 1;
  }
}
